 set maxErr = 5

&sql(Select ID,Name	Into :xID,:name
	From Ens_Config.Item 
	Where Name=:compNm)

if (SQLCODE = 0)
{

    set itm = ##class(Ens.Config.Item).%OpenId(xID)
    if ( (itm.GetSetting("MaxErrors", .pval) = 1) && ($GET(pval) > 0) )
    {
	    $$$TRACE( "GetSetting(MaxErrors): " _ $GET(pval))
    	set maxErr = pval
    }

}

Quit maxErr

