	set lastNm = ""
	if ($L(hddNmStr,",") > 1)
 {
    //has a comma in name
    set lastNm = $P(hddNmStr, ",", 1) 
 }
 else
 {
	 // Strip leading and trailing spaces 
	 set lastNm = $ZSTRIP(hddNmStr,"<>W")
 }
 return lastNm

	set firstNm = ""
 if ($L(hddNmStr,",") > 1)
 {
	//has a comma in name, get name before the space in the second part
 	set firstNm = $P($ZSTRIP($P(hddNmStr, ",", 2), "<W"), " ", 1)
 }
 return firstNm

 set midNm = ""
 if ($L(hddNmStr,",") > 1)
 {
	 set numNm = $L($ZSTRIP($P(hddNmStr, ",", 2), "<W"), " ")	
  if (numNm> 1)
  {
	  // has a space in second part of name
	  set midNm =  $P($ZSTRIP($P(hddNmStr, ",", 2), "<W"), " ", 2, numNm)
  }
 }
  return midNm

