  set retVal = val

  set strLen = ##class(Ens.Util.FunctionSet).Length(val)
  if strLen > 7 {
	  if strLen < 12 {
		set tStr=##class(Ens.Util.FunctionSet).SubString(val,1,8)_" 00:00"
	  }
	  else {
		set tStr=##class(Ens.Util.FunctionSet).SubString(val,1,8)_" "_##class(Ens.Util.FunctionSet).SubString(val,9,10)_":"_##class(Ens.Util.FunctionSet).SubString(val,11,12)
	  }
  	  set retVal = $ZDATETIME($ZDATETIMEH(tStr,8,1),8,7)
  	  set retVal=##class(Ens.Util.FunctionSet).ReplaceStr(retVal,"T","")
  	  set retVal=##class(Ens.Util.FunctionSet).ReplaceStr(retVal,":","")
  	  set retVal=##class(Ens.Util.FunctionSet).ReplaceStr(retVal,"Z","")
  }
  Quit retVal

	$$$TRACE("ExecuteShellCmd: " _ cmd)
	SET delim=" "
   		SET countdown=$LENGTH(cmd,delim)
   		SET countup=2
   		SET arrInd=1
   		SET cmdArr(1) = ""
   		set multiWord = 0
   		Set linuxCmd = $PIECE(cmd,delim,1)
   		$$$TRACE("In ExecuteShellCmd: " _ linuxCmd )
   		FOR reps=countdown:-1:1 {
      		SET extract=$PIECE(cmd,delim,countup)
           	if ( ($L(extract) '= 0) && (extract '= " ") ) {
	           	if ( (extract = """") && (multiWord = 0) )
	           	{
		           	set multiWord = 1
		           	SET countup = countup+1
		           	SET cmdArr(arrInd) = ""
		           	CONTINUE 
	           	}
	           	elseif ( (extract = """") && (multiWord = 1) )
	           	{
		           	set multiWord = 0
		           	$$$TRACE("Multi words: " _ cmdArr(arrInd))
		           	Set arrInd = arrInd + 1
		           	SET countup = countup+1
		           	CONTINUE 
	           	}
	           	if (multiWord = 1)
	           	{
		           	if ($L(cmdArr(arrInd)) = 0)
		           	{
			           	SET cmdArr(arrInd) = extract
		           	}
		           	else
		           	{
		           		SET cmdArr(arrInd) = cmdArr(arrInd) _ " " _ extract
		           	}
	           	}
	           	else
	           	{
      				SET cmdArr(arrInd) = "'" _ extract _ "'"
      				$$$TRACE("Array: (" _ arrInd _ "): " _ cmdArr(arrInd))
      				Set arrInd = arrInd + 1
	           	}
      		}
      		SET countup = countup+1
   		}
   		set flags = ""
   		if ($L(StdErr) > 0)
   		{
	   		set flags = "/STDERR=" _ """" _ StdErr _""""
	   		// set flags = "/STDERR=" _ StdErr
   		}
   		if ($L(StdOut) > 0)
   		{
	   		if ($L(flags) > 0)
	   		{
		   		set flags = flags _ " "
	   		}
	   		set flags = flags _ "/STDOUT=" _ """" _ StdOut _""""
	   		// set flags = flags _ "/STDOUT=" _  StdOut
   		}
   		if ( $L(flags) > 0)
   		{
	   		$$$TRACE("flags: " _ flags)
        	set stat = $ZF(-100,  flags _ " /SHELL", linuxCmd, .cmdArr)
   		}
   		else
   		{
	   		set stat = $ZF(-100,"/SHELL", linuxCmd, .cmdArr)
   		}
        $$$TRACE("Stat ExecuteShellCmd: " _ stat )
        return stat

  set retVal = 0
  if (str'="") {
	set tStream=##class(%Stream.GlobalCharacter).%New()
    Do tStream.Write(str)
    $$$TRACE("In method:hasSpecialChar()-String length: "_$L(str))
    set indx=1
    For { Set tchar=tStream.Read(1)  Quit:tchar=""
      if ($ASCII(tchar) > scStartVal) {
        set retVal=indx+1
        $$$TRACE("Found a special character at "_indx)
        break
      }
      else {
        set indx=indx+1
      }
    }
  }
  quit retVal
